PRAGMA foreign_keys=ON;
PRAGMA journal_mode=WAL;
CREATE TABLE IF NOT EXISTS goals(id TEXT PRIMARY KEY,title TEXT NOT NULL,domain TEXT NOT NULL,scope TEXT NOT NULL DEFAULT '',status TEXT NOT NULL DEFAULT 'INITIALIZING',created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS conversations(id TEXT PRIMARY KEY,goal_id TEXT NOT NULL REFERENCES goals(id),title TEXT NOT NULL,kind TEXT NOT NULL DEFAULT 'PLANNING',created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS messages(id TEXT PRIMARY KEY,conversation_id TEXT NOT NULL REFERENCES conversations(id),role TEXT NOT NULL CHECK(role IN ('user','assistant')),content TEXT NOT NULL,created_at TEXT NOT NULL,reply_to TEXT UNIQUE REFERENCES messages(id),host TEXT);
CREATE TABLE IF NOT EXISTS jobs(id TEXT PRIMARY KEY,message_id TEXT NOT NULL UNIQUE REFERENCES messages(id),conversation_id TEXT NOT NULL REFERENCES conversations(id),status TEXT NOT NULL CHECK(status IN ('QUEUED','RUNNING','COMPLETED','CANCELLED')),host TEXT,lease_token TEXT,lease_until INTEGER,created_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS idx_messages_conversation ON messages(conversation_id,created_at);
CREATE INDEX IF NOT EXISTS idx_jobs_queue ON jobs(status,created_at);
CREATE TABLE IF NOT EXISTS resources(id TEXT PRIMARY KEY,goal_id TEXT REFERENCES goals(id),title TEXT NOT NULL,url TEXT NOT NULL,role TEXT NOT NULL CHECK(role IN ('PRIMARY','SUPPLEMENTARY','REFERENCE')),saved INTEGER NOT NULL DEFAULT 0,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS resource_files(resource_id TEXT PRIMARY KEY REFERENCES resources(id),name TEXT NOT NULL,content BLOB NOT NULL);
CREATE TABLE IF NOT EXISTS notes(id TEXT PRIMARY KEY,goal_id TEXT REFERENCES goals(id),title TEXT NOT NULL,content TEXT NOT NULL,archived INTEGER NOT NULL DEFAULT 0,created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS prompts(id TEXT PRIMARY KEY,title TEXT NOT NULL,content TEXT NOT NULL,version INTEGER NOT NULL DEFAULT 1,updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS prompt_history(id INTEGER PRIMARY KEY,prompt_id TEXT NOT NULL,version INTEGER NOT NULL,content TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS proposals(id TEXT PRIMARY KEY,goal_id TEXT NOT NULL REFERENCES goals(id),title TEXT NOT NULL,summary TEXT NOT NULL,items TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'PENDING',created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS sessions(id TEXT PRIMARY KEY,goal_id TEXT NOT NULL REFERENCES goals(id),proposal_id TEXT NOT NULL REFERENCES proposals(id),title TEXT NOT NULL,objective TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'PLANNED',position INTEGER NOT NULL,conversation_id TEXT REFERENCES conversations(id));
CREATE TABLE IF NOT EXISTS evidence(id TEXT PRIMARY KEY,goal_id TEXT NOT NULL REFERENCES goals(id),conversation_id TEXT NOT NULL REFERENCES conversations(id),summary TEXT NOT NULL,mode TEXT NOT NULL,source_message_ids TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS profiles(goal_id TEXT PRIMARY KEY REFERENCES goals(id),content TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS profile_changes(id TEXT PRIMARY KEY,goal_id TEXT NOT NULL REFERENCES goals(id),evidence_id TEXT NOT NULL REFERENCES evidence(id),summary TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS receipts(request_id TEXT PRIMARY KEY,operation TEXT NOT NULL,result TEXT NOT NULL);
PRAGMA user_version=1;
